import json
import logging


DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY = "dkuLLMMeshRemainingStackDepth"
DKU_LLM_MESH_VIA_CONTEXT_KEY = "dkuLLMMeshVia"

LLM_MESH_STACK_DEPTH_REACHED_MESSAGE = "Maximum LLM mesh stack depth reached"

logger = logging.getLogger("dku.llm_mesh_stack")

try:
    from dataiku.base.contextvar_propagation import PropagatedContextVar
    _dku_llm_mesh_stack_depth_cv = PropagatedContextVar("dku_remaining_llm_mesh_stack_depth")
    _dku_llm_mesh_via_cv = PropagatedContextVar("dku_llm_mesh_via")
except Exception:
    # LLM mesh call stack tracking is disabled if PropagatedContextVar cannot be imported for any reason (e.g. Python version too old)
    logger.warning("Unable to initialize LLM mesh stack depth tracking", exc_info=True)
    _dku_llm_mesh_stack_depth_cv = None
    _dku_llm_mesh_via_cv = None

class LLMMeshStackDepthReachedError(Exception):
    pass


def _to_depth(raw_depth):
    if raw_depth is None:
        return None
    try:
        depth = int(raw_depth)
    except (TypeError, ValueError):
        return None
    if depth < 0:
        return None
    return depth


def _to_via(raw_via):
    if raw_via is None:
        return None
    if not isinstance(raw_via, list):
        return None
    if not all(isinstance(v, str) for v in raw_via):
        return None
    return list(raw_via)


def seed_llm_mesh_stack_depth_from_query(query):
    if _dku_llm_mesh_stack_depth_cv is None or _dku_llm_mesh_via_cv is None:
        # PropagatedContextVar not supported
        return
    if not isinstance(query, dict):
        _dku_llm_mesh_stack_depth_cv.set(None)
        _dku_llm_mesh_via_cv.set(None)
        return
    context = query.get("context")
    if not isinstance(context, dict):
        _dku_llm_mesh_stack_depth_cv.set(None)
        _dku_llm_mesh_via_cv.set(None)
        return

    if DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY in context:
        depth = _to_depth(context.get(DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY))
    else:
        depth = None
    _dku_llm_mesh_stack_depth_cv.set(depth)

    if DKU_LLM_MESH_VIA_CONTEXT_KEY in context:
        via = _to_via(context.get(DKU_LLM_MESH_VIA_CONTEXT_KEY))
    else:
        via = None
    _dku_llm_mesh_via_cv.set(via)


def prepare_query_for_nested_llm_mesh_call(query):
    if _dku_llm_mesh_stack_depth_cv is None or _dku_llm_mesh_via_cv is None:
        # PropagatedContextVar not supported
        return query
    if not isinstance(query, dict):
        return query

    input_context = query.get("context")
    if not isinstance(input_context, dict):
        input_context = {}

    if DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY in input_context:
        depth = _to_depth(input_context.get(DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY))
        inject_depth = False
    else:
        depth = _to_depth(_dku_llm_mesh_stack_depth_cv.get())
        inject_depth = depth is not None

    if DKU_LLM_MESH_VIA_CONTEXT_KEY in input_context:
        via = _to_via(input_context.get(DKU_LLM_MESH_VIA_CONTEXT_KEY))
        inject_via = False
    else:
        via = _to_via(_dku_llm_mesh_via_cv.get())
        inject_via = via is not None

    if depth is not None and depth <= 0:
        via_chain_json = json.dumps(via if via is not None else [], separators=(",", ":"))
        raise LLMMeshStackDepthReachedError(
            "%s. Potential recursive call cycle detected. LLM mesh via chain: %s"
            % (LLM_MESH_STACK_DEPTH_REACHED_MESSAGE, via_chain_json)
        )

    if not inject_depth and not inject_via:
        return query

    copied_query = dict(query)
    copied_context = dict(input_context)
    if inject_depth:
        copied_context[DKU_REMAINING_LLM_MESH_STACK_DEPTH_KEY] = depth
    if inject_via:
        copied_context[DKU_LLM_MESH_VIA_CONTEXT_KEY] = via
    copied_query["context"] = copied_context
    return copied_query


def is_llm_mesh_stack_depth_reached_error(error):
    if error is None:
        return False
    if isinstance(error, LLMMeshStackDepthReachedError):
        return True
    return LLM_MESH_STACK_DEPTH_REACHED_MESSAGE in str(error)
